      expect(mockUserRepository.findByEmail).toHaveBeenCalledWith(input.email);
      expect(mockUserRepository.findByUsername).toHaveBeenCalledWith(input.username);
      expect(mockUserRepository.create).toHaveBeenCalledWith({
