  // Middleware
  app.use(cors()); // RealWorld spec: accept all origins
  app.use(express.json());
  app.use(
    pinoHttp({
      level: env.LOG_LEVEL,
      redact: ['req.headers.authorization'] // Never log tokens
    })
  );

